using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Jobs;
using DuckDBWrapper = DuckDB.NET.Data;
using Parquet;
using Parquet.Serialization;
using ParquetBenchmarks.Models;

namespace ParquetBenchmarks.Benchmarks;

// Decodes the shared cross-language reference file (data/bench-1m.parquet,
// 1M rows, generated by python/make_reference.py and kept in the repo) so the
// C# and Python suites produce numbers from identical bytes. The Python
// counterpart is the SharedFile_* group in python/benchmark.py. The matched
// pair for cross-language comparison is SharedFile_DuckDb_AdoNet_ReadDecode
// (1M C# POCOs) vs SharedFile_DuckDb_FetchAll_ReadDecode (1M Python tuples):
// both fully materialize row objects through the same native DuckDB 1.5.5.
//
// Generate the file first:  cd python && uv run python make_reference.py

[MemoryDiagnoser]
[SimpleJob(RuntimeMoniker.Net10_0, warmupCount: 2, iterationCount: 5)]
public class SharedFileReadBenchmarks
{
    private const int RowCount = 1_000_000;
    private string _sharedPath = default!;

    [GlobalSetup]
    public void Setup()
    {
        // BenchmarkDotNet executes in a generated project several directories
        // below the repo root, so walk upwards until data/bench-1m.parquet
        // is found.
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "data", "bench-1m.parquet")))
            dir = dir.Parent;

        _sharedPath = dir is null
            ? throw new FileNotFoundException(
                "data/bench-1m.parquet not found - generate it with: cd python && uv run python make_reference.py")
            : Path.Combine(dir.FullName, "data", "bench-1m.parquet");
    }

    [Benchmark(Baseline = true)]
    public async Task<int> SharedFile_ParquetNet_ReadDecode()
    {
        await using var fs = File.OpenRead(_sharedPath);
        var rows = await ParquetSerializer.DeserializeAsync<BenchRow>(fs);
        return rows.Data.Count;
    }

    [Benchmark]
    public int SharedFile_ParquetSharp_Column_ReadDecode()
    {
        return ColumnParquetIo.Read(_sharedPath).Count;
    }

    [Benchmark]
    public async Task<int> SharedFile_ParquetSharp_Arrow_ReadDecode()
    {
        var rows = await ArrowParquetIo.ReadAsync(_sharedPath);
        return rows.Count;
    }

    [Benchmark]
    public int SharedFile_DuckDb_AdoNet_ReadDecode()
    {
        using var connection = new DuckDBWrapper.DuckDBConnection("DataSource=:memory:");
        connection.Open();

        using var cmd = connection.CreateCommand();
        cmd.CommandText =
            $"SELECT Id, Name, Price, CreatedAt, CreatedAtText, IsActive, Category, Rating, ExternalId, Description FROM read_parquet('{_sharedPath}');";
        using var reader = cmd.ExecuteReader();

        var list = new List<BenchRow>(RowCount);
        while (reader.Read())
        {
            list.Add(new BenchRow
            {
                Id = reader.GetInt64(0),
                Name = reader.GetString(1),
                Price = reader.GetFloat(2),
                CreatedAt = reader.GetDateTime(3),
                CreatedAtText = reader.GetString(4),
                IsActive = reader.GetBoolean(5),
                Category = reader.GetString(6),
                Rating = reader.GetDouble(7),
                ExternalId = reader.GetString(8),
                Description = reader.GetString(9)
            });
        }
        return list.Count;
    }
}
